h = hashlib.sha256()
for f in sorted(P.glob("*.csv")):
    h.update(f.name.encode() + b"\n" + f.read_bytes())
(Path(__file__).parent / "SEAL.sha256").write_text(h.hexdigest() + "  predictions/*.csv (sorted, name+bytes)\n")
print("files:", len(list(P.glob('*.csv'))), "seal:", h.hexdigest())
